/*!
 * Sideris portal: account calendar core (no DOM)
 *
 * Turns the official class plans (window.AE_TIMETABLE, generated by tools/build_timetable.py)
 * and the student's own record (localStorage 'ae_calendar') into dated occurrences, and merges
 * two records for cloud sync. Used by account/calendar.html, the dashboard and the sign-up
 * wizard. Spec: docs/superpowers/specs/2026-11-19-account-calendar-design.md.
 *
 * Record: { v: 1, updated, groups: { <slug>: { group, labGroup, slots: [{ id, dow, start, end,
 * room, kind }], at } }, marks: { <sessionId | occKey>: { status, note, time, room, moveTo, at } },
 * events: [{ id, subject, kind, title, date, start, end, room, note, links, at, deleted? }],
 * hidden: [{ id, at, deleted? }], daysOff: [YYYY-MM-DD] }
 */
(function () {
  'use strict';

  var KEY = 'ae_calendar';
  var CLASS_KINDS = { lecture: 1, problems: 1 };
  var KIND_LABEL = { lecture: 'Lecture', problems: 'Problem class', lab: 'Lab', test: 'Test', quiz: 'Quiz', exam: 'Exam', study: 'Study block', other: 'Event' };

  function empty() { return { v: 1, updated: 0, groups: {}, marks: {}, events: [], hidden: [], daysOff: [] }; }

  function normalise(rec) {
    var out = empty();
    if (!rec || typeof rec !== 'object') return out;
    out.updated = +rec.updated || 0;
    if (rec.groups && typeof rec.groups === 'object') out.groups = rec.groups;
    if (rec.marks && typeof rec.marks === 'object') out.marks = rec.marks;
    if (Array.isArray(rec.events)) out.events = rec.events;
    if (Array.isArray(rec.hidden)) out.hidden = rec.hidden;
    if (Array.isArray(rec.daysOff)) out.daysOff = rec.daysOff;
    return out;
  }

  function load() {
    try { return normalise(JSON.parse(localStorage.getItem(KEY) || 'null')); } catch (e) { return empty(); }
  }

  function save(rec) {
    try { rec.updated = Date.now(); localStorage.setItem(KEY, JSON.stringify(rec)); return true; } catch (e) { return false; }
  }

  // ------------------------------------------------------------------ dates (UTC, ISO strings)
  function parse(iso) { var p = iso.split('-'); return Date.UTC(+p[0], +p[1] - 1, +p[2]); }
  function iso(ms) { return new Date(ms).toISOString().slice(0, 10); }
  function addDays(isoDate, n) { return iso(parse(isoDate) + n * 86400000); }
  function dow(isoDate) { var d = new Date(parse(isoDate)).getUTCDay(); return d === 0 ? 7 : d; }
  function occKey(slug, date, start) { return slug + '@' + date + '@' + (start || 'day'); }

  function slotFor(slots, date) {
    var d = dow(date);
    for (var i = 0; i < (slots || []).length; i++) if (slots[i].dow === d) return slots[i];
    return null;
  }

  function isDayOff(tt, rec, slug, date) {
    if ((rec.daysOff || []).indexOf(date) >= 0) return true;
    var off = (tt && tt.term && tt.term.daysOff) || [];
    for (var i = 0; i < off.length; i++) {
      if (off[i].date === date && (!off[i].subjects || off[i].subjects.indexOf(slug) >= 0)) return true;
    }
    return false;
  }

  function base(slug, fields) {
    var o = { key: null, subject: slug, sessionId: null, kind: 'lecture', title: '', text: '', date: null, start: null, end: null,
      room: null, group: null, lab: null, links: [], status: null, note: '', official: false, basis: null, isEvent: false,
      isExam: false, allDay: false, manual: false, fromSlot: false, movedFrom: null };
    Object.keys(fields).forEach(function (k) { o[k] = fields[k]; });
    o.allDay = !o.start;
    return o;
  }

  function fromSession(slug, subj, s, extra) {
    return base(slug, Object.assign({
      sessionId: s.id, kind: s.kind, title: s.title, text: s.text, date: s.date, start: s.start, end: s.end, room: s.room,
      lab: s.lab, links: (s.links || []).slice(), official: true, basis: subj.basis
    }, extra || {}));
  }

  // ------------------------------------------------------------------ one subject
  function subjectOccurrences(tt, rec, slug) {
    var subj = tt && tt.subjects ? tt.subjects[slug] : null;
    var g = rec.groups[slug];
    if (!g) return [];
    var out = [];
    var official = subj && g.group !== 'custom' && subj.groups[g.group];
    var sessions = subj ? subj.sessions : [];
    var termStart = tt.term.start, termEnd = (subj && subj.termEnd) || tt.term.end;
    if (termEnd > tt.term.end) termEnd = tt.term.end;

    // Labs: only rows of this group (or of every group), filtered by lab group.
    sessions.forEach(function (s) {
      if (s.kind !== 'lab' || !s.date) return;
      if (s.groups && s.groups.indexOf(g.group) < 0) return;
      if (g.labGroup && s.lab && s.lab !== g.labGroup) return;
      var title = s.title + (!g.labGroup && s.lab ? ' (A or B)' : '');
      out.push(fromSession(slug, subj, s, { title: title, group: g.group }));
    });
    // Tests and quizzes keep their official date for every group.
    sessions.forEach(function (s) {
      if ((s.kind !== 'test' && s.kind !== 'quiz') || !s.date) return;
      var slot = official ? slotFor(official.slots, s.date) : null;
      out.push(fromSession(slug, subj, s, {
        start: s.start || (slot && slot.start) || null, end: s.end || (slot && slot.end) || null,
        room: s.room || (slot && slot.room) || null, group: g.group, isExam: true }));
    });

    if (official && official.dated) {
      sessions.forEach(function (s) {
        if (!CLASS_KINDS[s.kind] || !s.date) return;
        if (s.groups && s.groups.indexOf(g.group) < 0) return;
        var slot = slotFor(official.slots, s.date);
        out.push(fromSession(slug, subj, s, {
          start: s.start || (slot && slot.start) || null, end: s.end || (slot && slot.end) || null,
          room: s.room || (slot && slot.room) || null, group: g.group }));
      });
      return out;
    }

    // Own timetable: weekly slots across the term, minus days off.
    var slots = (official ? official.slots : g.slots) || [];
    var classes = [];
    for (var d = termStart; d <= termEnd; d = addDays(d, 1)) {
      if (isDayOff(tt, rec, slug, d)) continue;
      var wd = dow(d);
      slots.forEach(function (sl) {
        if (sl.dow !== wd || !sl.start) return;
        classes.push(base(slug, { kind: sl.kind || 'lecture', date: d, start: sl.start, end: sl.end, room: sl.room || null,
          group: g.group, manual: true, fromSlot: true, title: KIND_LABEL[sl.kind] || 'Lecture' }));
      });
    }
    classes.sort(function (a, b) { return (a.date + a.start) < (b.date + b.start) ? -1 : 1; });

    if (subj && subj.basis === 'log') {
      classes.forEach(function (c) {
        for (var i = 0; i < sessions.length; i++) {
          if (sessions[i].date === c.date) {
            var s = sessions[i];
            c.sessionId = s.id; c.title = s.title; c.text = s.text; c.links = s.links.slice(); c.official = true; c.basis = 'log'; c.manual = false;
            break;
          }
        }
      });
    } else if (subj) {
      var plan = sessions.filter(function (s) { return CLASS_KINDS[s.kind]; });
      var slotKinds = {}, planKinds = {};
      slots.forEach(function (s) { slotKinds[s.kind] = 1; });
      plan.forEach(function (s) { planKinds[s.kind] = 1; });
      var byKind = slotKinds.lecture && slotKinds.problems && planKinds.lecture && planKinds.problems;
      var queues = { all: plan.slice(), lecture: plan.filter(function (s) { return s.kind === 'lecture'; }),
        problems: plan.filter(function (s) { return s.kind === 'problems'; }) };
      classes.forEach(function (c) {
        var mark = rec.marks[occKey(slug, c.date, c.start)];
        if (mark && mark.status === 'notheld') return;
        var q = byKind ? queues[c.kind] || queues.all : queues.all;
        var s = q.shift();
        if (!s) return;
        if (!byKind) { /* single sequence */ } else { var i = queues.all.indexOf(s); if (i >= 0) queues.all.splice(i, 1); }
        c.sessionId = s.id; c.title = s.title; c.text = s.text; c.links = s.links.slice(); c.official = true;
        c.basis = 'plan'; c.manual = false; c.kind = s.kind;
      });
    }
    return out.concat(classes);
  }

  // ------------------------------------------------------------------ marks, events, exams
  function applyMark(o, rec) {
    var m = rec.marks[o.sessionId || o.key];
    if (!m) return o;
    if (m.moveTo && o.sessionId && !o.fromSlot) {
      o.movedFrom = o.date; o.date = m.moveTo; o.status = null;
    } else {
      o.status = m.status || null;
    }
    if (m.note) o.note = m.note;
    if (m.time && m.time.start) { o.start = m.time.start; o.end = m.time.end || o.end; o.allDay = false; }
    if (m.room) o.room = m.room;
    return o;
  }

  function live(list) { return (list || []).filter(function (x) { return x && !x.deleted; }); }

  function build(tt, rec, prefs, fromISO, toISO) {
    rec = normalise(rec);
    tt = tt || { term: { start: fromISO, end: toISO, daysOff: [] }, subjects: {} };
    prefs = prefs || {};
    var slugs = prefs.subjects && prefs.subjects.length ? prefs.subjects : Object.keys(rec.groups);
    var hidden = {};
    live(rec.hidden).forEach(function (h) { hidden[h.id] = true; });
    var out = [];
    slugs.forEach(function (slug) {
      subjectOccurrences(tt, rec, slug).forEach(function (o) {
        o.key = o.sessionId || occKey(slug, o.date, o.start);
        if (hidden[o.key]) return;
        out.push(applyMark(o, rec));
      });
      var ex = prefs.exams && prefs.exams[slug];
      if (ex) ['midterm', 'final'].forEach(function (kind) {
        if (!ex[kind]) return;
        var k = 'exam-' + slug + '-' + kind;
        if (hidden[k]) return;
        out.push(applyMark(base(slug, { key: k, kind: 'exam', isExam: true, date: ex[kind], official: false,
          title: kind === 'midterm' ? 'Midterm exam' : 'Final exam' }), rec));
      });
    });
    live(rec.events).forEach(function (e) {
      if (!e.date) return;
      var o = base(e.subject || null, { key: e.id, kind: e.kind || 'other', title: e.title || KIND_LABEL[e.kind] || 'Event',
        date: e.date, start: e.start || null, end: e.end || null, room: e.room || null, note: e.note || '',
        links: (e.links || []).slice(), isEvent: true, isExam: e.kind === 'exam' });
      out.push(applyMark(o, rec));
    });
    return out.filter(function (o) { return o.date >= fromISO && o.date <= toISO; })
      .sort(function (a, b) {
        var ka = a.date + (a.start || '00:00'), kb = b.date + (b.start || '00:00');
        return ka < kb ? -1 : ka > kb ? 1 : 0;
      });
  }

  function pending(occ, todayISO) {
    return occ.filter(function (o) { return o.status === 'missed' && o.date <= todayISO; });
  }

  function next(occ, nowISO) {
    var day = nowISO.slice(0, 10), time = nowISO.slice(11, 16);
    for (var i = 0; i < occ.length; i++) {
      var o = occ[i];
      if (o.status === 'notheld' || o.isExam || o.kind === 'study') continue;
      if (o.date > day || (o.date === day && o.start && o.start > time)) return o;
    }
    return null;
  }

  // ------------------------------------------------------------------ sync merge
  function newer(a, b) { return (b && (b.at || 0) > ((a && a.at) || 0)) ? b : a; }

  function mergeList(a, b) {
    var map = {}, order = [];
    (a || []).concat(b || []).forEach(function (x) {
      if (!x || !x.id) return;
      if (!map[x.id]) order.push(x.id);
      map[x.id] = map[x.id] ? newer(map[x.id], x) : x;
    });
    return order.map(function (id) { return map[id]; });
  }

  function merge(a, b) {
    a = normalise(a); b = normalise(b);
    var out = empty();
    out.updated = Math.max(a.updated, b.updated);
    Object.keys(a.groups).concat(Object.keys(b.groups)).forEach(function (k) { out.groups[k] = newer(a.groups[k], b.groups[k]) || b.groups[k]; });
    Object.keys(a.marks).concat(Object.keys(b.marks)).forEach(function (k) { out.marks[k] = newer(a.marks[k], b.marks[k]) || b.marks[k]; });
    out.events = mergeList(a.events, b.events);
    out.hidden = mergeList(a.hidden, b.hidden);
    a.daysOff.concat(b.daysOff).forEach(function (d) { if (out.daysOff.indexOf(d) < 0) out.daysOff.push(d); });
    out.daysOff.sort();
    return out;
  }

  // ------------------------------------------------------------------ revision plan before an exam
  function hm(min) { var h = Math.floor(min / 60), m = min % 60; return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m; }
  function toMin(t) { var p = t.split(':'); return +p[0] * 60 + +p[1]; }

  // Topics an exam covers: "Topics 4, 5, 6 and 7" in its text, each with the plan sessions that
  // teach it; without a list, every plan session of the subject before the exam, grouped by its
  // first link.
  function examTopics(tt, rec, exam) {
    var subj = tt.subjects[exam.subject];
    if (!subj) return [];
    var sessions = subj.sessions.filter(function (s) { return CLASS_KINDS[s.kind] && (!s.date || s.date < exam.date); });
    var m = /Topics?\s+([\d,\sand]+)/i.exec(exam.text || exam.title || '');
    var groups = [];
    if (m) {
      (m[1].match(/\d+/g) || []).forEach(function (n) {
        var re = new RegExp('Topic ' + n + '\\b', 'i');
        var ss = subj.sessions.filter(function (s) { return CLASS_KINDS[s.kind] && re.test(s.title); });
        if (ss.length) groups.push({ label: ss[0].title.replace(/\s+I+V?$/, ''), sessions: ss });
      });
    } else {
      var byLink = {};
      sessions.forEach(function (s) {
        var l = s.links[0];
        if (!l) return;
        var k = l.href.split('#')[0];
        if (!byLink[k]) { byLink[k] = { label: l.label, sessions: [] }; groups.push(byLink[k]); }
        byLink[k].sessions.push(s);
      });
    }
    groups.forEach(function (g) {
      var seen = {};
      g.links = [];
      g.missed = g.sessions.some(function (s) { var mk = rec.marks[s.id]; return mk && mk.status === 'missed'; });
      g.sessions.forEach(function (s) { s.links.forEach(function (l) { if (!seen[l.href]) { seen[l.href] = 1; g.links.push(l); } }); });
    });
    return groups.filter(function (g) { return g.missed; }).concat(groups.filter(function (g) { return !g.missed; }));
  }

  // An empty plan says why: 'no-topics' (the plan lists nothing the exam covers), 'no-days'
  // (no class day left before it) or 'no-time' (no free hour on those days).
  function because(list, reason) { list.reason = reason; return list; }

  function revisionPlan(tt, rec, prefs, exam, todayISO, hoursPerDay) {
    rec = normalise(rec);
    var topics = examTopics(tt, rec, exam);
    if (!topics.length) return because([], 'no-topics');
    var len = Math.max(30, Math.round((hoursPerDay || 1) * 60));
    var days = [];
    for (var d = addDays(todayISO, 1); d < exam.date; d = addDays(d, 1)) if (!isDayOff(tt, rec, exam.subject, d)) days.push(d);
    if (!days.length) return because([], 'no-days');
    var busy = {};
    days.forEach(function (day) {
      busy[day] = build(tt, rec, prefs, day, day).filter(function (o) { return o.start && o.status !== 'notheld'; })
        .map(function (o) { return [toMin(o.start), o.end ? toMin(o.end) : toMin(o.start) + 60]; });
    });
    var candidates = [];
    for (var h = 17 * 60; h + len <= 22 * 60; h += 30) candidates.push(h);
    for (h = 9 * 60; h < 17 * 60; h += 30) candidates.push(h);
    var out = [], n = Math.max(topics.length, days.length);
    for (var k = 0; k < n; k++) {
      var day = days[k % days.length], topic = topics[k % topics.length];
      var start = null;
      for (var i = 0; i < candidates.length; i++) {
        var s = candidates[i], e = s + len;
        if (!busy[day].some(function (b) { return s < b[1] && b[0] < e; })) { start = s; break; }
      }
      if (start === null) continue;
      busy[day].push([start, start + len]);
      out.push({ id: 'rev-' + exam.key + '-' + k, subject: exam.subject, kind: 'study', title: 'Revise: ' + topic.label + (k >= topics.length ? ' (second pass)' : ''),
        date: day, start: hm(start), end: hm(start + len), room: '', note: '', links: topic.links.slice(), exam: exam.key, at: Date.now() });
    }
    if (!out.length) return because(out, 'no-time');
    return out.sort(function (a, b) { return (a.date + a.start) < (b.date + b.start) ? -1 : 1; });
  }

  // ------------------------------------------------------------------ attendance
  function attendance(occ, todayISO) {
    var out = {};
    occ.forEach(function (o) {
      if (o.isEvent || o.isExam || !o.subject || o.date > todayISO) return;
      if (!(CLASS_KINDS[o.kind] || o.kind === 'lab')) return;
      var a = out[o.subject] = out[o.subject] || { held: 0, attended: 0, missed: 0, caughtUp: 0 };
      if (o.status === 'notheld') return;
      a.held++;
      if (o.status === 'missed' || o.status === 'done') a.missed++;
      if (o.status === 'done') a.caughtUp++;
    });
    Object.keys(out).forEach(function (k) { out[k].attended = out[k].held - out[k].missed; });
    return out;
  }

  // ------------------------------------------------------------------ iCalendar export (RFC 5545)
  var SUBJECT_SHORT = { 'fluid-mechanics': 'Fluids', 'aerospace-materials-1': 'Materials', 'engineering-mechanics': 'Mechanics', 'advanced-maths': 'Maths', 'business-management': 'Management' };
  var VTIMEZONE = ['BEGIN:VTIMEZONE', 'TZID:Europe/Madrid',
    'BEGIN:DAYLIGHT', 'TZOFFSETFROM:+0100', 'TZOFFSETTO:+0200', 'TZNAME:CEST', 'DTSTART:19700329T020000', 'RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=-1SU', 'END:DAYLIGHT',
    'BEGIN:STANDARD', 'TZOFFSETFROM:+0200', 'TZOFFSETTO:+0100', 'TZNAME:CET', 'DTSTART:19701025T030000', 'RRULE:FREQ=YEARLY;BYMONTH=10;BYDAY=-1SU', 'END:STANDARD',
    'END:VTIMEZONE'];

  function icsText(s) { return String(s || '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n'); }
  function fold(line) {
    var out = [];
    while (line.length > 74) { out.push(line.slice(0, 74)); line = ' ' + line.slice(74); }
    out.push(line);
    return out.join('\r\n');
  }
  function icsDate(d) { return d.replace(/-/g, ''); }
  function icsTime(d, t) { return icsDate(d) + 'T' + t.replace(':', '') + '00'; }

  function toICS(occ, nowISO) {
    // DTSTAMP is UTC (RFC 5545): nowISO is local time, so convert it.
    var t = new Date(nowISO);
    var stamp = isNaN(t.getTime()) ? new Date().toISOString() : t.toISOString();
    stamp = stamp.replace(/[-:]/g, '').slice(0, 15) + 'Z';
    var lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Sideris//Calendar//EN', 'CALSCALE:GREGORIAN'].concat(VTIMEZONE);
    occ.forEach(function (o) {
      if (o.status === 'notheld') return;
      var who = SUBJECT_SHORT[o.subject] ? SUBJECT_SHORT[o.subject] + ': ' : '';
      lines.push('BEGIN:VEVENT', 'UID:' + (o.key || o.id) + '@sideris', 'DTSTAMP:' + stamp);
      if (o.start) {
        var end = o.end || hm(toMin(o.start) + 60);
        lines.push('DTSTART;TZID=Europe/Madrid:' + icsTime(o.date, o.start), 'DTEND;TZID=Europe/Madrid:' + icsTime(o.date, end));
      } else {
        lines.push('DTSTART;VALUE=DATE:' + icsDate(o.date), 'DTEND;VALUE=DATE:' + icsDate(addDays(o.date, 1)));
      }
      lines.push('SUMMARY:' + icsText(who + (o.title || KIND_LABEL[o.kind] || 'Class')));
      if (o.room) lines.push('LOCATION:' + icsText(o.room));
      var desc = [o.text, o.note, o.status === 'missed' ? 'Missed: to catch up.' : ''].filter(Boolean).join('\n');
      if (desc) lines.push('DESCRIPTION:' + icsText(desc));
      lines.push('END:VEVENT');
    });
    lines.push('END:VCALENDAR');
    return lines.map(fold).join('\r\n') + '\r\n';
  }

  window.AECalendar = {
    KEY: KEY, KIND_LABEL: KIND_LABEL, empty: empty, load: load, save: save, build: build, pending: pending, next: next,
    merge: merge, occKey: occKey, addDays: addDays, dow: dow, revisionPlan: revisionPlan, attendance: attendance, toICS: toICS
  };
})();
